class FfiConverterTypeKeyValueStore: FfiConverter<KeyValueStore, IntPtr> {
    public ConcurrentHandleMap<KeyValueStore> handleMap = new ConcurrentHandleMap<KeyValueStore>();
    
    public static FfiConverterTypeKeyValueStore INSTANCE = new FfiConverterTypeKeyValueStore();


    public override IntPtr Lower(KeyValueStore value) {
        return (IntPtr)handleMap.Insert(value);
    }

    public override KeyValueStore Lift(IntPtr value) {
        return new KeyValueStoreImpl(value);
    }

    public override KeyValueStore Read(BigEndianStream stream) {
        return Lift(new IntPtr(stream.ReadLong()));
    }

    public override int AllocationSize(KeyValueStore value) {
        return 8;
    }

    public override void Write(KeyValueStore value, BigEndianStream stream) {
        stream.WriteLong(Lower(value).ToInt64());
    }
}



