            + FfiConverterUInt32.INSTANCE.AllocationSize(value.@wordCount)
            + FfiConverterDouble.INSTANCE.AllocationSize(value.@durationSeconds)
            + FfiConverterTypeHwTranscriptStatus.INSTANCE.AllocationSize(value.@status);
    }

