/// <summary>
/// Whether and when to retry a failed attempt. Mirrors `hw_net::RetryDecision`.
/// </summary>
internal record RetryDecision {
    
    public record Retry (
        ulong @delayMs
    ) : RetryDecision {}
    
    public record GiveUp: RetryDecision {}
    
    

    
}

class FfiConverterTypeRetryDecision : FfiConverterRustBuffer<RetryDecision>{
    public static FfiConverterRustBuffer<RetryDecision> INSTANCE = new FfiConverterTypeRetryDecision();

    public override RetryDecision Read(BigEndianStream stream) {
        var value = stream.ReadInt();
        switch (value) {
            case 1:
                return new RetryDecision.Retry(
                    FfiConverterUInt64.INSTANCE.Read(stream)
                );
            case 2:
                return new RetryDecision.GiveUp(
                );
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRetryDecision.Read()", value));
        }
    }

    public override int AllocationSize(RetryDecision value) {
        switch (value) {
            case RetryDecision.Retry variant_value:
                return 4
                    + FfiConverterUInt64.INSTANCE.AllocationSize(variant_value.@delayMs);
            case RetryDecision.GiveUp variant_value:
                return 4;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRetryDecision.AllocationSize()", value));
        }
    }

    public override void Write(RetryDecision value, BigEndianStream stream) {
        switch (value) {
            case RetryDecision.Retry variant_value:
                stream.WriteInt(1);
                FfiConverterUInt64.INSTANCE.Write(variant_value.@delayMs, stream);
                break;
            case RetryDecision.GiveUp variant_value:
                stream.WriteInt(2);
                break;
            default:
                throw new InternalException(String.Format("invalid enum value '{0}' in FfiConverterTypeRetryDecision.Write()", value));
        }
    }
}







